package com.bank.join;

import java.util.*;
import java.util.logging.*;

public class JoiningDemo {
    private static final Logger log = Logger.getLogger("Join");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> names = List.of("Rajesh", "Priya", "Amit");
        JoinService service = new JoinService();

        log.info(() -> "csv     : " + service.toCsvLine(names));
        log.info(() -> "bracketed: " + service.toBracketed(names));
        log.info(() -> "empty   : " + service.toCsvLine(List.of()));
    }
}

// ─── Would be in service/JoinService.java ───
class JoinService {
    String toCsvLine(List<String> items) {
        return items.stream()
            .collect(java.util.stream.Collectors.joining(", "));        // "a, b, c"
    }
    String toBracketed(List<String> items) {
        return items.stream()
            .collect(java.util.stream.Collectors.joining(", ", "[", "]")); // "[a, b, c]"
    }
}
